     7	
     8	public class Loan {
     9	
    10	    static final int LOAN_PERIOD_DAYS = 14;
    11	    static final long LATE_FEE_PER_DAY = 100;
    12	
    13	    private final UUID id;
    14	    private final UUID bookId;
    15	    private final UUID memberId;
    16	    private final LocalDate loanedAt;
    17	    private final LocalDate dueAt;
    18	    private LocalDate returnedAt;
    19	
    20	    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
    21	        this.id = Objects.requireNonNull(id, "id");
    22	        this.bookId = Objects.requireNonNull(bookId, "bookId");
    23	        this.memberId = Objects.requireNonNull(memberId, "memberId");
    24	        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
    25	        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
    26	        if (dueAt.isBefore(loanedAt)) {
    27	            throw new IllegalArgumentException("dueAt must not be before loanedAt");
    28	        }
    29	        this.returnedAt = returnedAt;
    30	    }
    31	
    32	    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    33	    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
    34	        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null);
    35	    }
    36	
    37	    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
    38	                                    LocalDate returnedAt) {
    39	        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    40	    }
    41	
    42	    public void markReturned(LocalDate returnedAt) {
    43	        if (isReturned()) {
    44	            throw new LoanAlreadyReturnedException(id);
    45	        }
    46	        Objects.requireNonNull(returnedAt, "returnedAt");
    47	        if (returnedAt.isBefore(loanedAt)) {
    48	            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
    49	        }
    50	        this.returnedAt = returnedAt;
    51	    }
    52	
    53	    public boolean isReturned() {
    54	        return returnedAt != null;
    55	    }
