    29	    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, LoadMemberPort loadMemberPort,
    30	                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort) {
    31	        this.loadBookPort = loadBookPort;
    32	        this.saveBookPort = saveBookPort;
    33	        this.loadMemberPort = loadMemberPort;
    34	        this.loadLoanPort = loadLoanPort;
    35	        this.saveLoanPort = saveLoanPort;
    36	    }
    37	
    38	    @Override
    39	    public Loan loanBook(LoanBookCommand command) {
    40	        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
    41	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
    42	        member.ensureCanBorrow(loadLoanPort.countActiveLoansByMemberId(member.getId()));
    43	
    44	        Book book = loadBookPort.loadBook(command.bookId())
    45	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    46	        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
    47	        Loan loan = book.loanTo(command.memberId(), loanedAt);
    48	        saveBookPort.saveBook(book);
    49	        saveLoanPort.saveLoan(loan);
    50	        return loan;
    51	    }
